from modele import chapitre,E,Q,tableau
from pedagogie import page,bloc

chapitre(13,'aires-angles','Aires et angles : comparer','3 · Grandeurs et mesures',
'Surfaces · Pavages · Centimètre carré · Écartements',
['Comparer des aires par superposition, découpage ou pavage.','Mesurer une aire en carreaux ou en centimètres carrés.','Comparer des angles et repérer les angles droits.'],
['Quadrillages et figures usuelles.'],[
page(1,'Comparer et mesurer des aires',
bloc('definition',r'L’aire d’une figure est la mesure de l’étendue de sa surface. Deux figures peuvent être comparées en les superposant, ou en découpant l’une pour recouvrir l’autre, sans rien mesurer.'),
bloc('savoirfaire',r'Sur un quadrillage, on choisit un carreau comme unité d’aire : l’aire est le nombre de carreaux qui pavent la figure. Deux demi-carreaux comptent pour un carreau entier.','Paver pour mesurer'),
bloc('definition',r'Le centimètre carré, noté $\mathrm{cm}^2$, est l’aire d’un carré de 1 cm de côté. Une figure pavée par 12 de ces carrés a une aire de 12 $\mathrm{cm}^2$.'),
bloc('attention',r'Aire et périmètre sont deux grandeurs différentes : l’une mesure la surface, l’autre le contour. Deux figures de même périmètre peuvent avoir des aires différentes, et réciproquement.')),
page(2,'Comparer des angles',
bloc('definition',r'Un angle est l’écartement entre deux côtés qui partent d’un même sommet. L’angle de sommet B, dont les côtés passent par A et C, se note $\widehat{ABC}$ : la lettre du sommet est au milieu.'),
r'@FIG:cours-angles@',
bloc('savoirfaire',r'Pour comparer deux angles, décalquer l’un et le poser sur l’autre, sommet sur sommet et un côté sur l’autre : le plus ouvert est le plus grand. La longueur dessinée des côtés ne change pas l’angle.','Comparer avec un calque'),
bloc('propriete',r'L’angle droit est l’angle du coin de l’équerre. Un angle peut être plus petit, égal ou plus grand qu’un angle droit : c’est le premier repère pour classer les angles.'))
],[
E('Qui a la plus grande aire ?',r'Comparer les aires des deux figures grisées du quadrillage.',r'La première couvre 8 carreaux, la seconde 7 : la première a $\res{\text{la plus grande aire}}$.','Compter les carreaux de chaque figure.','assert 8>7',figure='aa-1'),
E('Mesurer en carreaux',r'Donner l’aire de la figure en L, en carreaux.',r'La figure se découpe en un rectangle de 4 carreaux et un carré de 3 carreaux au-dessous : $4+3=\res7$ carreaux.','Découper la figure en morceaux simples.','assert 4+3==7',figure='aa-2'),
E('Formes différentes, aires égales',r'Montrer que les deux figures ont la même aire.',r'Chacune couvre $\res6$ carreaux : même aire, formes différentes. Déplacer un carreau ne change pas l’aire.','Compter puis comparer.','assert 6==6',figure='aa-3'),
E('En centimètres carrés',r'Chaque carreau du quadrillage est un carré de 1 cm de côté. Donner l’aire du rectangle.',r'Le rectangle couvre 4 rangées de 3 carreaux : $4\times3=\res{12\ \mathrm{cm}^2}$.','Compter les carreaux rangée par rangée.','assert 4*3==12',figure='aa-4'),
E('Nommer un angle',r'Nommer l’angle marqué sur la figure, préciser son sommet et ses côtés.',r'C’est l’angle $\widehat{ABC}$ : son sommet est $\res B$, ses côtés passent par A et par C. La lettre du sommet s’écrit au milieu, sous le chapeau.','Repérer d’abord le sommet.','assert 1==1',figure='aa-5'),
E('Ranger des angles',r'Ranger les trois angles dessinés du plus fermé au plus ouvert.',r'En superposant un calque, l’ordre est $\res{\widehat{B}<\widehat{A}<\widehat{C}}$. Les longueurs des côtés dessinés ne comptent pas.','Comparer les écartements, pas les longueurs.','assert 1<2<3',figure='aa-6'),
E('Chercher les angles droits',r'Avec une équerre, repérer les angles droits du quadrilatère dessiné.',r'L’équerre s’ajuste exactement en A et en D : la figure possède $\res2$ angles droits, marqués d’un petit carré.','Poser le coin de l’équerre sur chaque sommet.','assert 2<=4',figure='aa-7'),
E('Des moitiés de carreaux',r'Donner l’aire de la figure, qui contient des carreaux entiers et des demi-carreaux.',r'On compte 4 carreaux entiers et 2 demi-carreaux : $4+1=\res5$ carreaux. Deux moitiés se réunissent en un carreau entier.','Associer les demi-carreaux deux par deux.','assert 4+1==5',figure='aa-8'),
E('Même tour, autre surface',r'Vérifier que les deux rectangles ont le même périmètre, puis comparer leurs aires.',r'Périmètres : $2\times(5+1)=12$ et $2\times(3+3)=12$ : égaux. Aires : $5\times1=5$ carreaux contre $3\times3=9$ carreaux : le carré a $\res{\text{la plus grande aire}}$. Même périmètre ne signifie pas même aire.','Calculer séparément contour et surface.','assert 2*(5+1)==12 and 2*(3+3)==12 and 5*1==5 and 3*3==9',figure='aa-9'),
E('L’angle du calque',r'Un angle décalqué se superpose exactement sur un angle de la figure. Lequel ? Justifier.',r'Le calque coïncide, sommet sur sommet et côtés sur côtés, avec l’angle $\res{\widehat{E}}$ : deux angles superposables sont égaux, même si leurs côtés dessinés ont des longueurs différentes.','Superposer sommet et un côté avant de conclure.','assert 1==1',figure='aa-10'),
E('Les deux parcelles',r'Sur le plan, chaque carreau représente 1 $\mathrm m^2$. Comparer les aires des parcelles P et Q, puis donner l’aire de la plus grande.',r'P couvre 12 carreaux et Q en couvre 10, moitiés regroupées. P a la plus grande aire : $\res{12\ \mathrm m^2}$ contre 10 $\mathrm m^2$.','Compter carreaux entiers puis moitiés.','assert 12>10',figure='aa-11'),
E('La frise de triangles',r'La frise est pavée de triangles tous identiques, chacun valant un demi-carreau. Donner son aire en carreaux.',r'On compte 14 triangles ; deux triangles font un carreau : $14:2=\res7$ carreaux.','Convertir les triangles en carreaux.','assert 14//2==7',figure='aa-12'),
E('Le côté qui double',r'Un carré a 2 carreaux de côté. On double son côté.'+Q(r'Donner l’aire du petit et du grand carré.',r'L’aire a-t-elle doublé ?'),r'Petit carré : $2\times2=\res4$ carreaux. Grand carré : $4\times4=\res{16}$ carreaux. L’aire est multipliée par $16:4=4$ : elle $\res{\text{a quadruplé}}$, et non doublé.','Compter les carreaux des deux carrés.','assert 2*2==4 and 4*4==16 and 16//4==4',figure='aa-13'),
E('Les angles du triangle',r'Comparer chaque angle du triangle dessiné à l’angle droit de l’équerre.',r'L’angle en A est $\res{\text{droit}}$ : l’équerre s’y ajuste. Les angles en B et en C sont $\res{\text{plus petits}}$ qu’un angle droit : l’équerre dépasse.','Tester chaque sommet avec l’équerre.','assert 1==1',figure='aa-14'),
E('Grand tour, petite aire',r'Milan affirme : « Plus le périmètre d’une figure est grand, plus son aire est grande. » Comparer le serpentin et le carré dessinés, puis répondre.',r'Le serpentin a un contour de $\res{20}$ unités, le carré de $\res{12}$ unités seulement. Pourtant chacun couvre $\res9$ carreaux : même aire ! L’affirmation est $\res{\text{fausse}}$ : contour et surface sont des grandeurs indépendantes.','Mesurer les deux grandeurs sur chaque figure.','assert 20>12 and 9==9',figure='aa-15')
],reperes=['Comparer des surfaces','Pavages et centimètre carré','Angles, sommet et notation','Angle droit et classements'],deco='grandeurs')

chapitre(14,'durees','Horaires et durées','3 · Grandeurs et mesures',
'Heures · Minutes · Instants · Temps écoulé',
['Lire l’heure sur une horloge à aiguilles.','Convertir des durées entre heures et minutes.','Calculer un début, une fin ou une durée.'],
['Division euclidienne et addition posée.'],[
page(1,'Lire l’heure',
bloc('definition',r'Sur une horloge à aiguilles, la petite aiguille indique les heures, la grande les minutes. Chaque graduation d’heure vaut 5 minutes pour la grande aiguille : quand elle pointe le 7, il est 35 minutes.'),
r'@FIG:cours-horloge@',
bloc('propriete',r'Un jour dure 24 heures et une heure dure 60 minutes. L’après-midi, on ajoute 12 aux heures du cadran : 2 h de l’après-midi s’écrit 14 h ; 20 h 30 se dit aussi « 8 h 30 du soir ».'),
bloc('savoirfaire',r'Convertir en passant par 60 : $1$ h $30$ min $=60+30=90$ min ; et 180 min $=3\times60$ min $=3$ h. Pour 95 min : $95=60+35$, soit 1 h 35 min.','Minutes et heures')),
page(2,'Calculer des durées',
bloc('savoirfaire',r'Pour la durée entre 9 h 40 et 10 h 15, avancer par étapes : de 9 h 40 à 10 h, 20 min ; de 10 h à 10 h 15, 15 min. Total : 35 min. Une frise des instants aide à poser les étapes.','Avancer par étapes'),
bloc('exemple',r'Heure de fin : partir de 10 h 20 et durer 45 min. $10$ h $20+40$ min $=11$ h, puis encore 5 min : 11 h 05. Heure de début : finir à 12 h 05 après 30 min, c’est partir à 11 h 35.'),
bloc('attention',r'Un horaire est un instant ; une durée est un temps écoulé. On n’additionne pas deux horaires. Dans les calculs, 60 minutes s’échangent contre une heure : il n’existe pas d’horaire à 70 minutes.'),
bloc('propriete',r'Pour comparer des durées, les exprimer dans la même unité : 1 h 15 min $=75$ min est plus court que 80 min.'))
],[
E('Lire deux horloges',r'Lire l’heure affichée par chacune des deux horloges, le matin.',r'Première horloge : $\res{7\ \text h\ 15}$. Seconde : la grande aiguille sur le 7 indique 35 min, il est $\res{10\ \text h\ 35}$.','Lire la petite aiguille puis la grande.','assert 7*60+15==435 and 10*60+35==635',figure='hor-1'),
E('Placer les aiguilles',r'Dessiner les aiguilles d’une horloge indiquant 16 h 45.',r'Sur le cadran, 16 h se lit 4 h. La grande aiguille pointe le 9 (45 min) et la petite approche du 5 : le dessin figure en vert sur le corrigé.','Convertir l’heure de l’après-midi sur le cadran.','assert 16-12==4 and 45==9*5',figure='hor-2'),
E('Matin ou après-midi',r'Écrire en heures de l’après-midi ou du soir : 15 h ; 20 h 30. Écrire avec les heures du jour : « 5 h du soir ».',r'$15$ h $=\res{3\ \text h\ \text{de l’après-midi}}$ ; $20$ h $30=\res{8\ \text h\ 30\ \text{du soir}}$. « 5 h du soir » s’écrit $\res{17\ \text h}$.','Ajouter ou retirer 12 heures.','assert 15-12==3 and 20-12==8 and 5+12==17'),
E('Convertir',r'Convertir : 2 h en minutes ; 1 h 30 min en minutes ; 180 min en heures.',r'$2\times60=\res{120}$ min ; $60+30=\res{90}$ min ; $180=3\times60$, soit $\res3$ h.','Passer par 60 minutes pour une heure.','assert 2*60==120 and 60+30==90 and 180//60==3'),
E('Dans la même heure',r'Un cours commence à 14 h 10 et finit à 14 h 45. Combien de temps dure-t-il ?',r'Les heures sont les mêmes : $45-10=\res{35}$ min.','Soustraire les minutes.','assert 45-10==35'),
E('Franchir l’heure',r'Quelle durée s’écoule entre 9 h 40 et 10 h 15 ?',r'De 9 h 40 à 10 h : 20 min. De 10 h à 10 h 15 : 15 min. Total : $20+15=\res{35}$ min.','Faire étape à l’heure ronde.','assert (10*60+15)-(9*60+40)==35 and 20+15==35'),
E('L’heure de fin',r'Un entraînement commence à 10 h 20 et dure 45 min. À quelle heure finit-il ?',r'$10$ h $20+40$ min $=11$ h, puis 5 min : fin à $\res{11\ \text h\ 05}$.','Compléter d’abord jusqu’à l’heure ronde.','assert (10*60+20)+45==11*60+5'),
E('L’heure de départ',r'Un trajet de 30 min se termine à 12 h 05. À quelle heure a-t-il commencé ?',r'On recule : 5 min pour revenir à 12 h, puis 25 min : départ à $\res{11\ \text h\ 35}$. Contrôle : $11$ h $35+30$ min $=12$ h 05.','Reculer par étapes depuis la fin.','assert (12*60+5)-30==11*60+35'),
E('Des minutes aux heures',r'Convertir 95 min en heures et minutes, puis 2 h 05 min en minutes.',r'$95=60+35$ : $\res{1\ \text h\ 35}$. Et $2\times60+5=\res{125}$ min.','Extraire les paquets de 60 minutes.','assert divmod(95,60)==(1,35) and 2*60+5==125'),
E('La plus longue durée',r'Qui écoute le plus de musique : Ana pendant 1 h 15 min ou Bob pendant 80 min ?',r'$1$ h $15=75$ min et $75<80$ : $\res{\text{Bob}}$ écoute 5 min de plus.','Tout convertir en minutes.','assert 60+15==75 and 80-75==5'),
E('La séance de cinéma',r'Un film commence à 14 h 50 et dure 1 h 45 min. À quelle heure se termine-t-il ?',r'$14$ h $50+1$ h $=15$ h 50, puis 10 min pour atteindre 16 h, puis 35 min : fin à $\res{16\ \text h\ 35}$.','Ajouter l’heure entière puis les minutes par étapes.','assert (14*60+50)+105==16*60+35'),
E('La journée de classe',r'La classe travaille de 8 h 30 à 11 h 45, puis de 13 h 30 à 16 h 30. Calculer la durée totale de classe.',r'Matin : de 8 h 30 à 11 h 30, 3 h, puis 15 min : 3 h 15. Après-midi : $\res{3\ \text h}$ exactement. Total : $3$ h $15+3$ h $=\res{6\ \text h\ 15}$ de classe.','Calculer chaque demi-journée puis additionner.','assert (11*60+45)-(8*60+30)==195 and (16*60+30)-(13*60+30)==180 and 195+180==375 and divmod(375,60)==(6,15)',figure='hor-12'),
E('Le train de 9 h 48',r'Un train part à 9 h 48 et arrive à 11 h 23. Combien de temps dure le voyage ?',r'De 9 h 48 à 10 h : 12 min. De 10 h à 11 h : 1 h. De 11 h à 11 h 23 : 23 min. Durée : $12+60+23=95$ min, soit $\res{1\ \text h\ 35}$.','Découper le trajet aux heures rondes.','assert (11*60+23)-(9*60+48)==95 and divmod(95,60)==(1,35)'),
E('Les départs du bus',r'Un bus part toutes les 20 minutes ; le premier départ est à 7 h. Écrire les horaires de départ jusqu’à 8 h inclus. Combien y a-t-il de départs entre 7 h et 9 h, les deux horaires compris ?',r'Départs : 7 h, 7 h 20, 7 h 40, $\res{8\ \text h}$. De 7 h à 9 h, cela fait $120:20=6$ intervalles, donc $6+1=\res7$ départs : on compte le départ de 7 h.','Compter les intervalles puis ajouter le premier départ.','assert 120//20==6 and 6+1==7'),
E('Le gâteau au four',r'Un gâteau doit cuire 55 min. Il est enfourné à 17 h 40 et sorti à 18 h 30. Est-il resté assez longtemps au four ?',r'De 17 h 40 à 18 h 30 : $20+30=50$ min. Il fallait 55 min : il est sorti $\res{5\ \text{min trop tôt}}$. L’heure correcte de sortie était $\res{18\ \text h\ 35}$.','Comparer la durée réelle à la durée demandée.','assert (18*60+30)-(17*60+40)==50 and 55-50==5 and (17*60+40)+55==18*60+35')
],reperes=['Lecture de l’heure','Conversions heures-minutes','Durées entre deux instants','Horaires de début et de fin'],deco='grandeurs')
